const { setWorldConstructor, setDefaultTimeout } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const assert = require('assert');
const fs = require('fs');
const path = require('path');

class TodoWorld {
  constructor() {
    this.window = new Window({ url: 'http://localhost:3000/' });
    this.document = this.window.document;

    const htmlPath = path.join(__dirname, '..', '..', 'src', 'index.html');
    const html = fs.readFileSync(htmlPath, 'utf-8');
    this.document.body.innerHTML = html;

    const appPath = path.join(__dirname, '..', '..', 'src', 'app.js');
    const appCode = fs.readFileSync(appPath, 'utf-8');
    this.window.eval(appCode);

    this.app = this.window.app;
  }

  findTodoLi(title) {
    const li = this.findTodoLiOrNull(title);
    assert.ok(li, 'Todo "' + title + '" should exist in the DOM');
    return li;
  }

  findTodoLiOrNull(title) {
    const items = this.document.querySelectorAll('.todo-list li');
    for (let i = 0; i < items.length; i++) {
      const label = items[i].querySelector('label');
      if (label && label.textContent === title) return items[i];
    }
    return null;
  }
}

